def drawMaze():

    pen = turtle.Turtle()
    pen.width(2)
    pen.teleport(-len(rows)*15, -len(columns)*15)

    num = 0

    for i in rows:
        for x in i:
            if x == 1:
                pen.forward(15)
            elif x == 0:
                pen.up()
                pen.forward(15)
                pen.down()
            num += 1
        pen.goto((len(rows)-num)*15,(len(columns))*15)

drawMaze()

